ROOT.scriptdef:
set nocount on;
declare @PGLId int;

If (select count(*) from cdn.PoleceniaGlowne where PGL_PredefiniowaneID>0) >0
begin
	delete from cdn.PoleceniaGlowne where PGL_PredefiniowaneID>0
end

